INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(31811, 'John 6:39', 'John', 6, 39, 'چا چې زه رالېږلی یم د هغه رضا دا ده چې ټول خلک چې هغه ماته راکړي دي یو یې هم له لاسه ورنه کړم بلکې د اخرت په ورځ هغوی راژوندي کړم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john6_verse_39.mp3', '', 1761754199, 1761754199),
(31812, 'John 6:40', 'John', 6, 40, 'ځکه چې زما د پلار رضا دا ده چې هرڅوک چې ما د هغه د زوی په توګه وپېژني او په ما باندې ایمان راوړي، هغه به د تلپاتې ژوندون خاوند شي او زه به هغه د اخرت په ورځ راژوندی کړم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john6_verse_40.mp3', '', 1761754199, 1761754199),
(31813, 'John 6:41', 'John', 6, 41, 'په دې باندې خلک په خپلو کې سره وغورېدل، ځکه چې هغه وویل: «زه هغه ډوډۍ یم چې د اسمان نه نازل شوې ده.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john6_verse_41.mp3', '', 1761754199, 1761754199),
(31814, 'John 6:42', 'John', 6, 42, 'نو هغوی وویل: «ایا دا سړی د یوسف زوی عیسی نه دی چې مونږ یې مور او پلار پېژنو؟ نو بیا هغه څنګه وایي چې زه د اسمان نه راښکته شوی یم؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john6_verse_42.mp3', '', 1761754199, 1761754199),
(31815, 'John 6:43', 'John', 6, 43, 'عیسی ځواب ورکړ: «په خپل منځ کې سره مه غورېږئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john6_verse_43.mp3', '', 1761754199, 1761754199),
(31816, 'John 6:44', 'John', 6, 44, 'هېڅوک نه شي کولای چې ماته راشي ترڅو هغه پلار چې زه یې رالېږلی یم هغه ماته رانه ولي، او زه به هغه د اخرت په ورځ راژوندی کړم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john6_verse_44.mp3', '', 1761754199, 1761754199),
(31817, 'John 6:45', 'John', 6, 45, 'د پیغمبرانو په کتابونو کې لیکل شوي دي: هغوی ټول به د خدای له خوا تعلیم حاصل کړي. هرڅوک چې د پلار خبرو ته غوږ ونیسي او د هغه څخه څه زده کړي، هغه ماته راځي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john6_verse_45.mp3', '', 1761754199, 1761754199),
(31818, 'John 6:46', 'John', 6, 46, 'هېچا پلار نه دی لیدلی پرته د هغه چا نه چې د خدای له خوا راغلی دی. یوازې هغه خدای لیدلی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john6_verse_46.mp3', '', 1761754199, 1761754199),
(31819, 'John 6:47', 'John', 6, 47, 'په یقین سره زه تاسو ته دا وایم چې څوک چې په ما باندې ایمان راوړي هغه د تلپاتې ژوندون خاوند دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john6_verse_47.mp3', '', 1761754199, 1761754199),
(31820, 'John 6:48', 'John', 6, 48, 'زه هغه ډوډۍ یم چې ژوندون ورکوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john6_verse_48.mp3', '', 1761754199, 1761754199),
(31821, 'John 6:49', 'John', 6, 49, 'سره له دې چې ستاسو نیکونو په دښته کې د من ډوډۍ وخوړله، خو هغوی مړه شول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john6_verse_49.mp3', '', 1761754199, 1761754199),
(31822, 'John 6:50', 'John', 6, 50, 'خو کومه ډوډۍ چې د اسمان څخه رانازلیږي هغه داسې ډوډۍ ده چې هرڅوک هغه وخوري، نو هېڅکله به نه مړ کیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john6_verse_50.mp3', '', 1761754199, 1761754199),
(31823, 'John 6:51', 'John', 6, 51, 'زه د ژوندون هغه ډوډۍ یم چې د اسمان څخه رانازل شوې ده. هرڅوک چې دا ډوډۍ وخوري، نو هغه به تل ترتله ژوندی وي. کومه ډوډۍ چې زه به یې ورکوم، هغه زما خپل بدن دی چې زه یې د نړۍ د ژوندون په خاطر ورکوم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john6_verse_51.mp3', '', 1761754199, 1761754199),
(31824, 'John 6:52', 'John', 6, 52, 'په دې خبره یهودیانو په خپل منځ کې سره سخت بحث پیل کړ او ویل یې: «دا سړی څنګه کولای شي چې خپل بدن مونږ ته راکړي چې ویې خورو؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john6_verse_52.mp3', '', 1761754199, 1761754199),
(31825, 'John 6:53', 'John', 6, 53, 'عیسی هغوی ته وویل: «په یقین سره زه تاسو ته دا وایم چې تر هغې پورې چې تاسو د انسان د زوی بدن ونه خورئ او د هغه وینه ونه څښئ، نو تاسو به تلپاتې ژوندون ونه لرئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john6_verse_53.mp3', '', 1761754199, 1761754199),
(31826, 'John 6:54', 'John', 6, 54, 'هرڅوک چې زما بدن وخوري او زما وینه وڅښي، نو هغه به د تلپاتې ژوندون خاوند وي او زه به هغه د اخرت په ورځ راژوندی کړم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john6_verse_54.mp3', '', 1761754199, 1761754199),
(31827, 'John 6:55', 'John', 6, 55, 'ځکه چې زما بدن رښتیني خواړه دي او زما وینه رښتینې څښاک ده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john6_verse_55.mp3', '', 1761754199, 1761754199),
(31828, 'John 6:56', 'John', 6, 56, 'هرڅوک چې زما بدن وخوري او زما وینه وڅښي، نو هغه به په ما کې وي او زه به په هغه کې یم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john6_verse_56.mp3', '', 1761754199, 1761754199),
(31829, 'John 6:57', 'John', 6, 57, 'لکه څنګه چې اسماني پلار چې ژوند ورکوي زه راولېږلم او زه د هغه له امله ژوندی یم، نو په همدې ډول هرڅوک چې زما بدن وخوري نو هغه به زما له امله ژوندی وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john6_verse_57.mp3', '', 1761754199, 1761754199),
(31830, 'John 6:58', 'John', 6, 58, 'دا هغه ډوډۍ ده چې د اسمان څخه رانازله شوې ده او دا د هغې ډوډۍ په شان نه ده چې ستاسو نیکونو وخوړله او مړه شول. هرڅوک چې دا ډوډۍ وخوري، نو هغه به تل ترتله ژوندی وي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john6_verse_58.mp3', '', 1761754199, 1761754199),
(31831, 'John 6:59', 'John', 6, 59, 'دا خبرې عیسی هغه وخت په کنیسه کې وکړلې کله چې هغه په کپرناحوم کې تعلیم ورکاوه. د تلپاتې ژوندون خبرې', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john6_verse_59.mp3', '', 1761754199, 1761754199),
(31832, 'John 6:60', 'John', 6, 60, 'د هغه ډېرو پیروانو چې کله دا خبرې واورېدلې نو ویې ویل: «دا ډېره سخته ده، څوک کولای شي دا خبرې ومني؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john6_verse_60.mp3', '', 1761754199, 1761754199),
(31833, 'John 6:61', 'John', 6, 61, 'عیسی په خپل زړه کې پوه شو چې شاګردان یې په دې خبره باندې غوریږي، نو هغوی ته یې وویل: «ایا تاسو په دې باندې خفه شوئ؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john6_verse_61.mp3', '', 1761754199, 1761754199),
(31834, 'John 6:62', 'John', 6, 62, 'که چېرې تاسو د انسان زوی ووینئ چې بېرته هغه ځای ته ورخېژي چې پخوا په کې ؤ، نو تاسو به څه فکر وکړئ؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john6_verse_62.mp3', '', 1761754199, 1761754199),
(31835, 'John 6:63', 'John', 6, 63, 'دا د خدای روح دی چې انسانانو ته ژوند وربخښي، انساني قوت هېڅ نه شي کولای. ما چې تاسو ته کومې خبرې کړې دي هغه هم روح دی او هم ژوندون.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john6_verse_63.mp3', '', 1761754199, 1761754199),
(31836, 'John 6:64', 'John', 6, 64, 'خو بیاهم په تاسو کې ځینې خلک شته چې په ما ایمان نه لري.» ځکه چې عیسی ته د هماغې ورځې نه چې تعلیم یې پیل کړ دا معلومه وه چې څوک به ایمان نه راوړي او څوک به د هغه سره خیانت کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john6_verse_64.mp3', '', 1761754199, 1761754199),
(31837, 'John 6:65', 'John', 6, 65, 'بیا هغه وویل: «په همدې سبب ما تاسو ته وویل چې هېڅوک نه شي کولای ماته راشي، ترڅو پورې چې پلار ورته دا توان ورکړی نه وي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john6_verse_65.mp3', '', 1761754199, 1761754199),
(31838, 'John 6:66', 'John', 6, 66, 'د دې خبرې نه وروسته د عیسی ډېرو پیروانو هغه پرېښود او نور یې د هغه ملګرتیا ونه کړه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john6_verse_66.mp3', '', 1761754199, 1761754199),
(31839, 'John 6:67', 'John', 6, 67, 'نو عیسی د دولسو شاګردانو څخه پوښتنه وکړه: «ایا تاسو هم غواړئ چې ما پرېږدئ؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john6_verse_67.mp3', '', 1761754199, 1761754199),
(31840, 'John 6:68', 'John', 6, 68, 'شمعون پطروس ځواب ورکړ: «ای استاذه، مونږ به چاته لاړ شو؟ ستا سره هغه خبرې دي چې تلپاتې ژوندون ورکوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john6_verse_68.mp3', '', 1761754199, 1761754199),
(31841, 'John 6:69', 'John', 6, 69, 'مونږ په تا باندې ایمان راوړی دی او په دې باندې پوه شوي یو چې ته د خدای سپېڅلی یې.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john6_verse_69.mp3', '', 1761754199, 1761754199),
(31842, 'John 6:70', 'John', 6, 70, 'عیسی ځواب ورکړ: «ایا تاسو دولس واړه ما غوره نه کړئ؟ خو بیاهم په تاسو کې یو تن شیطان دی!»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john6_verse_70.mp3', '', 1761754199, 1761754199),
(31843, 'John 6:71', 'John', 6, 71, 'عیسی دا خبرې د شمعون اسخریوتي د زوی یهودا په هکله کولې، که څه هم هغه د دولسو شاګردانو څخه ؤ، هغه وروسته د عیسی سره خیانت وکړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john6_verse_71.mp3', '', 1761754199, 1761754199),
(31844, 'Revelation 12:1', 'Revelation', 12, 1, 'نو بیا په اسمان کې یوه لویه نښه ښکاره شوه. هلته یوه ښځه وه چې لمر یې لکه د کالیو په شان اغوستی ؤ، سپوږمۍ یې تر پښو لاندې وه او په سر باندې یې د دولسو ستورو تاج ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation12_verse_1.mp3', '', 1761754199, 1761754199),
(31845, 'Revelation 12:2', 'Revelation', 12, 2, 'هغه امیدواره وه او د لنګون د درد له امله یې چیغې وهلې او په تکلیف وه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation12_verse_2.mp3', '', 1761754199, 1761754199),
(31846, 'Revelation 12:3', 'Revelation', 12, 3, 'بیا په اسمان کې یوه بله نښه ښکاره شوه. هلته یو لوی سور ښامار ؤ چې اووه سرونه او لس ښکرونه یې لرل او په هر سر باندې یې تاج ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation12_verse_3.mp3', '', 1761754199, 1761754199),
(31847, 'Revelation 12:4', 'Revelation', 12, 4, 'هغه په خپلې لکۍ باندې د اسمان درېمه برخه ستوري راکش کړل او په ځمکه یې راوغورځول. ښامار د هغې ښځې په مخکې چې د ماشوم د زېږولو په حال کې وه ودرېده، د دې دپاره چې کله د هغې ماشوم پیدا شي، هغه یې ژوندی تېر کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation12_verse_4.mp3', '', 1761754199, 1761754199),
(31848, 'Revelation 12:5', 'Revelation', 12, 5, 'بیا د هغې زوی پیدا شو چې په ټولو قومونو به د اوسپنې په امسا باندې حکومت کوي. خو د هغې ماشوم پورته د خدای او د هغه تخت ته یووړل شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation12_verse_5.mp3', '', 1761754199, 1761754199),
(31849, 'Revelation 12:6', 'Revelation', 12, 6, 'هغه ښځه دښتې ته، یعنې هغه ځای ته وتښتېدله چې خدای ورته تیار کړی ؤ، ترڅو هلته د یو زر او دوه سوه شپېته ورځو دپاره د هغې پالنه وشي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation12_verse_6.mp3', '', 1761754199, 1761754199),
(31850, 'Revelation 12:7', 'Revelation', 12, 7, 'بیا په اسمان کې جنګ وشو. میکاییل او د هغه فرښتو د ښامار سره او ښامار او د هغه فرښتو د دوی سره جنګ وکړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation12_verse_7.mp3', '', 1761754199, 1761754199),
(31851, 'Revelation 12:8', 'Revelation', 12, 8, 'خو ښامار ماتې وخوړه او نور د هغه او د هغه د فرښتو دپاره په اسمان کې ځای نه ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation12_verse_8.mp3', '', 1761754199, 1761754199),
(31852, 'Revelation 12:9', 'Revelation', 12, 9, 'نو هغه لوی ښامار لاندې وغورځول شو، هغه زوړ او پخوانی مار چې د شیطان یا ابلیس په نوم یادیږي او ټوله نړۍ یې غولوله، د خپلو فرښتو سره لاندې ځمکې ته وغورځول شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation12_verse_9.mp3', '', 1761754199, 1761754199),
(31853, 'Revelation 12:10', 'Revelation', 12, 10, 'بیا مې په اسمان کې یو لوړ اواز واورېد چې ویل یې: اوس دی وخت رارسېدلی زمونږ د خدای د خلاصون او د قدرت، پاچاهۍ او د هغه ټاکل شوي مسیح د واک او اختیار ځکه څوک چې مدعي ؤ زمونږ د خویندو ورونو او شپه او ورځ یې لګول په هغوی باندې تورونه د خدای حضور کې غورځول شوی دی د اسمان نه لاندې ځمکې ته دا', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation12_verse_10.mp3', '', 1761754199, 1761754199),
(31854, 'Revelation 12:11', 'Revelation', 12, 11, 'او بریالي شول زمونږ خویندې ورونه په وسیله د وري د وینې او په هغه باندې د شاهدۍ د پیغام ځکه تیار وو هغوی دې ته چې خپل ژوند له لاسه ورکړي او حتی مړه شي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation12_verse_11.mp3', '', 1761754199, 1761754199),
(31855, 'Revelation 12:12', 'Revelation', 12, 12, 'وکړئ خوشحالي ای اسمانونو او چې په کې اوسئ تاسو خو ای ځمکې او بحره! افسوس دې وي ستاسو په حال باندې ځکه درغی شیطان تاسو ته ښکته او ښه پوهیږي په دې چې زیات وخت ورسره نشته نو ډېر په قهر دی هغه', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation12_verse_12.mp3', '', 1761754199, 1761754199),
(31856, 'Revelation 12:13', 'Revelation', 12, 13, 'کله چې ښامار پوه شو چې ځمکې ته راغورځول شوی دی، نو د هغې ښځې پسې شو چې زوی یې زېږولی ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation12_verse_13.mp3', '', 1761754199, 1761754199),
