(31899, 'Acts 8:38', 'Acts', 8, 38, 'نو هغه مامور امر وکړ چې ګاډۍ ودروي. فیلیپوس او هغه دواړه اوبو ته ورښکته شول او فیلیپوس هغه ته د تعمید غسل ورکړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts8_verse_38.mp3', '', 1761754199, 1761754199),
(31900, 'Acts 8:39', 'Acts', 8, 39, 'کله چې هغوی دواړه له اوبو څخه راووتل، نو د څښتن روح فیلیپوس بوته او هغه مامور نور فیلیپوس ونه لیده او په خوشحالۍ سره په خپله لاره روان شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts8_verse_39.mp3', '', 1761754199, 1761754199),
(31901, 'Acts 8:40', 'Acts', 8, 40, 'خو فیلیپوس پوه شو چې زه د اشدود په ښار کې یم. هغه په ټولو ښارونو کې ګرځېده او زېری یې ورکاوه، ترڅو قیصریې ته ورسېده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts8_verse_40.mp3', '', 1761754199, 1761754199),
(31902, 'Mark 11:1', 'Mark', 11, 1, 'کله چې عیسی او د هغه شاګردان اورشلیم ته نژدې شول او بیت‌فاجي او بیت‌عنیا ته چې د زیتون په غره کې وو ورسېدل، نو عیسی خپل دوه شاګردان ولېږل', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark11_verse_1.mp3', '', 1761754199, 1761754199),
(31903, 'Mark 11:2', 'Mark', 11, 2, 'او هغوی ته یې وویل: «مخامخ کلي ته ورشئ. څنګه چې هلته ورننوتلئ، نو هلته به یو کوټی ووینئ چې تړل شوی به وي او تر‌اوسه پورې څوک ورباندې سپور شوی نه دی. هغه را‌ایله کړئ او دلته یې راولئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark11_verse_2.mp3', '', 1761754199, 1761754199),
(31904, 'Mark 11:3', 'Mark', 11, 3, 'که څوک درڅخه پوښتنه وکړي: دا څه کوئ؟ نو ورته ووایئ چې هغه زمونږ د استاذ په کار دی او سمدلاسه به یې بېرته دلته راولېږي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark11_verse_3.mp3', '', 1761754199, 1761754199),
(31905, 'Mark 11:4', 'Mark', 11, 4, 'هغوی لاړل او دباندې په کوڅه کې یې یو کوټی ولیده چې د دروازې په مخکې تړل شوی ؤ. کله چې هغوی هغه کوټی راخلاصولو،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark11_verse_4.mp3', '', 1761754199, 1761754199),
(31906, 'Mark 11:5', 'Mark', 11, 5, 'نو ځینې خلک چې په هغه ځای کې ولاړ وو، د هغوی څخه پوښتنه وکړه: «دا کوټی ولې ایله کوئ؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark11_verse_5.mp3', '', 1761754199, 1761754199),
(31907, 'Mark 11:6', 'Mark', 11, 6, 'نو لکه څنګه چې عیسی ورته ویلي وو، دوی ورته هماغسې ځواب ورکړ او بیا یې هغوی پرېښودل چې لاړ شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark11_verse_6.mp3', '', 1761754199, 1761754199),
(31908, 'Mark 11:7', 'Mark', 11, 7, 'هغوی هغه کوټی عیسی ته راوست او خپلې چپنې یې ورباندې واچولې او عیسی ورباندې سپور شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark11_verse_7.mp3', '', 1761754199, 1761754199),
(31909, 'Mark 11:8', 'Mark', 11, 8, 'ډېرو خلکو ورته په لاره کې خپل کالي وغوړول او نورو د ونو څانګې راپرې کړلې او په لاره کې یې ورته واچولې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark11_verse_8.mp3', '', 1761754199, 1761754199),
(31910, 'Mark 11:9', 'Mark', 11, 9, 'او کوم خلک چې د هغه څخه مخکې روان وو او هغه چې شاته ورپسې روان وو، چیغې وهلې: «ژوندی دې وي! مبارک دې وي هغه څوک چې د څښتن په نوم راځي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark11_verse_9.mp3', '', 1761754199, 1761754199);